{
  "name": "cicd-demo-app",
  "version": "1.0.0",
  "description": "Sample Node.js App for CI/CD demonstration",
  "main": "src/app.js",
  "scripts": {
    "start": "node src/app.js",
    "test": "jest --colors",
    "build": "echo 'Application build completed successfully!'"
  },
  "devDependencies": {
    "jest": "^29.7.0"
  }
}

function add(a, b) {
  return a + b;
}

function multiply(a, b) {
  return a * b;
}

module.exports = { add, multiply };

const { add, multiply } = require('../src/app');

describe('Math Operations Test Suite', () => {
  test('correctly adds two numbers: 5 + 7 = 12', () => {
    expect(add(5, 7)).toBe(12);
  });

  test('correctly multiplies two numbers: 4 * 6 = 24', () => {
    expect(multiply(4, 6)).toBe(24);
  });
});

pipeline {
    agent any

    tools {
        nodejs 'NodeJS-20'
    }

    stages {
        stage('Checkout') {
            steps {
                echo 'Checking out source code from Git repository...'
                checkout scm
            }
        }

        stage('Install') {
            steps {
                echo 'Installing project dependencies using npm...'
                sh 'npm install' // On Windows Jenkins use: bat 'npm install'
            }
        }

        stage('Test') {
            steps {
                echo 'Executing Jest automated unit test suite...'
                sh 'npm test' // On Windows Jenkins use: bat 'npm test'
            }
        }

        stage('Build') {
            steps {
                echo 'Executing application production build...'
                sh 'npm run build' // On Windows Jenkins use: bat 'npm run build'
            }
        }
    }

    post {
        success {
            echo 'CI/CD Pipeline executed successfully! All tests passed.'
        }
        failure {
            echo 'Pipeline failed. Check test reports and build console.'
        }
    }
}

public class HelloDocker {
    public static void main(String[] args) {
